// Invoked by C library wrapper _exit(2)
// Terminates the entire thread group immediately,
// bypassing cleanup handlers and buffered output flushing.

// status (int): The exit status code
void force_termination(int status) {

    // Internal glibc mechanism calls exit_group(status)
    // if glibc >= 2.3 and thread group > 1 thread.
    _exit(status);

    // Execution halts here.
    // Code below this line is unreachable.
}

force_termination(0);
// Process is guaranteed dead.
